    /// Helper: create a minimal valid PlanTemplate for testing.
    fn make_test_template(name: &str) -> PlanTemplate {
        let step = StepDefinition::new(
            "step-1".into(),
            "test_tool".into(),
            serde_json::json!({}),
            false,
            "Test step".into(),
            None,
        );
        let now = chrono::Utc::now();
        PlanTemplate::new(
            name.into(),
            "Test description".into(),
            "1.0.0".into(),
            vec![],
            vec![step],
            None,
            std::collections::HashMap::new(),
            now,
            now,
        )
        .expect("Failed to create test template")
    }

    /// Mock converter for testing the TemplateConverter contract.
    struct MockTemplateConverter;

    #[async_trait::async_trait]
    impl TemplateConverter for MockTemplateConverter {
        async fn to_toml(&self, template: &PlanTemplate) -> Result<String, TemplateError> {
            Ok(format!(
                r#"name = "{}"
description = "{}"
version = "{}"
"#,
                template.name(),
                template.description(),
                template.version()
            ))
        }

        async fn to_json(&self, template: &PlanTemplate) -> Result<serde_json::Value, TemplateError> {
            Ok(serde_json::json!({
                "name": template.name(),
                "description": template.description(),
                "version": template.version(),
                "tags": template.tags(),
                "step_count": template.steps().len(),
            }))
        }

        async fn from_toml(&self, toml_str: &str) -> Result<PlanTemplate, TemplateError> {
            let name = toml_str
                .lines()
                .find(|l| l.starts_with("name = "))
                .and_then(|l| l.split('"').nth(1))
                .unwrap_or("unknown")
                .to_string();

            // Produce a valid template from the TOML metadata
            let step = StepDefinition::new(
                "step-1".into(),
                "test_tool".into(),
                serde_json::json!({}),
                false,
                "Parsed step".into(),
                None,
            );
            let now = chrono::Utc::now();
            PlanTemplate::new(
                name,
                "Parsed from TOML".into(),
                "0.1.0".into(),
                vec![],
                vec![step],
                None,
                std::collections::HashMap::new(),
                now,
                now,
            )
        }

        async fn from_json(
            &self,
            json: serde_json::Value,
        ) -> Result<PlanTemplate, TemplateError> {
            PlanTemplate::from_json(json)
        }

        async fn validate_toml(&self, _toml_str: &str) -> Result<(), TemplateError> {
            Ok(())
        }

        async fn validate_and_convert(
            &self,
            json: serde_json::Value,
        ) -> Result<PlanTemplate, TemplateError> {
            PlanTemplate::from_json(json)
        }
    }

