    #[tokio::test]
    async fn test_template_converter_from_json_valid() {
        let converter = MockTemplateConverter;
        let json = serde_json::json!({
            "name": "from-json",
            "description": "Created from JSON",
            "version": "1.0.0",
            "tags": ["test"],
            "steps": [{
                "name": "step-1",
                "tool": "test_tool",
                "parameters": {},
                "requires_approval": false,
                "description": "Test step"
            }],
            "constraints": null,
            "metadata": {},
            "created_at": "2026-01-01T00:00:00Z",
            "updated_at": "2026-01-01T00:00:00Z"
        });
        let template = converter
            .from_json(json)
            .await
            .expect("Should deserialize valid JSON");
        assert_eq!(template.name(), "from-json");
        assert_eq!(template.steps().len(), 1);
    }

